/**
 * Brand fonts for the PDF quote generated by the project cost calculator.
 *
 * The quote used to be a screenshot of the on-page invoice panel; it is now a
 * real vector document, so it needs the site's own typefaces embedded to still
 * read as a Grasshopper document. These are the same three families the site
 * loads from Google Fonts (Outfit / Inter / Space Mono), subset down to the
 * glyphs a quote can contain.
 *
 * Loaded lazily - only when a visitor actually asks for a PDF - so the
 * calculator page itself carries none of this weight.
 *
 * GENERATED FILE - do not hand-edit. Rebuilt with fontTools from the upstream
 * Google Fonts sources (github.com/google/fonts: ofl/outfit, ofl/inter,
 * ofl/spacemono), variable axes pinned as noted per font below. Inter keeps
 * Latin-1 + Latin Ext-A + Cyrillic + the Unicode currency block because it
 * renders the money figures and visitor-typed page names; Outfit and Space
 * Mono only ever render fixed English chrome, so they are basic Latin.
 *
 * Fonts are licensed under the SIL Open Font License 1.1.
 */
(function (jsPDFAPI) {
  "use strict";

  // Outfit 700 - display headings
  var Outfit_Bold = "";

  // Inter 400 - body copy and amounts
  var Inter_Regular = "";

  // Inter 700 - emphasis and totals
  var Inter_Bold = "";

  // Space Mono 400 - meta labels
  var SpaceMono = "";

  jsPDFAPI.events.push(["addFonts", function () {
    this.addFileToVFS("Outfit-Bold.ttf", Outfit_Bold);
    this.addFont("Outfit-Bold.ttf", "Outfit", "bold");
    this.addFileToVFS("Inter-Regular.ttf", Inter_Regular);
    this.addFont("Inter-Regular.ttf", "Inter", "normal");
    this.addFileToVFS("Inter-Bold.ttf", Inter_Bold);
    this.addFont("Inter-Bold.ttf", "Inter", "bold");
    this.addFileToVFS("SpaceMono.ttf", SpaceMono);
    this.addFont("SpaceMono.ttf", "SpaceMono", "normal");
  }]);
})(window.jspdf.jsPDF.API);
